/* Service worker: makes Kaidoneta installable and fully offline (a regional venue's signal is never good).
 * The file list and version below are GENERATED by tools/update-sw.js (run it after editing any file).
 * Each version is cached whole under its own name and old caches are deleted, so nobody runs a mix of old and new
 * files. Requests to other sites (the online crew) are never cached. */
const VERSION = 'kaido-aac9f5f588';
const SHELL = [
  /* BEGIN SHELL */
  './',
  'index.html',
  'manifest.webmanifest',
  'css/style.css',
  'js/app.js',
  'js/art-dragon.js',
  'js/art.js',
  'js/cloud.js',
  'js/core.js',
  'js/crew.js',
  'js/fx.js',
  'js/kaido-backlit.js',
  'js/kaido-bust.js',
  'js/kaido-hybrid.js',
  'js/kaido-ukiyoe.js',
  'js/log.js',
  'js/native.js',
  'js/player.js',
  'js/tools.js',
  'js/update.js',
  'icons/apple-touch-icon.png',
  'icons/badge.jpg',
  'icons/favicon.png',
  'icons/icon-192.png',
  'icons/icon-512.png',
  'icons/icon-maskable-512.png',
  'icons/icon.svg',
  'fonts/OFL-playfair.txt',
  'fonts/OFL.txt',
  'fonts/playfair-900.woff2',
  'fonts/rubik-dirt.woff2'
  /* END SHELL */
];

self.addEventListener('install', (event) => {
  event.waitUntil(
    caches.open(VERSION)
      .then((cache) => cache.addAll(SHELL.map((url) => new Request(url, { cache: 'reload' }))))
      .then(() => self.skipWaiting())
  );
});

self.addEventListener('activate', (event) => {
  event.waitUntil(
    caches.keys()
      .then((keys) => Promise.all(keys.filter((k) => k.startsWith('kaido-') && k !== VERSION).map((k) => caches.delete(k))))
      .then(() => self.clients.claim())
  );
});

self.addEventListener('fetch', (event) => {
  const req = event.request;
  if (req.method !== 'GET' || new URL(req.url).origin !== self.location.origin) return;
  event.respondWith(
    caches.match(req, { ignoreSearch: true }).then((hit) => hit || fetch(req).then((res) => {
      if (res.ok) { const copy = res.clone(); caches.open(VERSION).then((c) => c.put(req, copy)); }
      return res;
    }).catch(() => caches.match('index.html')))
  );
});
